display.text:
use std::sync::LazyLock;

use aho_corasick::AhoCorasick;
use itertools::Itertools;
use memchr::memchr_iter;
use regex::{Regex, RegexSet};
use ruff_diagnostics::{Diagnostic, Edit, Fix, FixAvailability, Violation};
use ruff_macros::{derive_message_formats, ViolationMetadata};
use ruff_python_parser::parse_module;
use ruff_python_trivia::{is_python_whitespace, CommentRanges, SimpleTokenKind, SimpleTokenizer};
use ruff_source_file::{LineRanges, UniversalNewlineIterator};
use ruff_text_size::{Ranged, TextLen, TextRange, TextSize};

use crate::directives::{TodoComment, TodoDirective, TodoDirectiveKind};
use crate::settings::LinterSettings;
use crate::Locator;

/// ## What it does
/// Checks for commented-out Python code.
///
/// ## Why is this bad?
/// Commented-out code is dead code, and is often included inadvertently.
/// It should be removed.
///
/// ## Known problems
/// Prone to false positives when checking comments that resemble Python code,
/// but are not actually Python code ([#4845]).
///
/// ## Example
/// ```python
/// # print("Hello, world!")
/// ```
///
/// ## Options
/// - `lint.task-tags`
///
/// [#4845]: https://github.com/astral-sh/ruff/issues/4845
#[derive(ViolationMetadata)]
pub(crate) struct CommentedOutCode;

impl Violation for CommentedOutCode {
    const FIX_AVAILABILITY: FixAvailability = FixAvailability::None;

    #[derive_message_formats]
    fn message(&self) -> String {
        "Found commented-out code".to_string()
    }

    fn fix_title(&self) -> Option<String> {
        Some("Remove commented-out code".to_string())
    }
}

static CODE_INDICATORS: LazyLock<AhoCorasick> = LazyLock::new(|| {
    AhoCorasick::new([
        "(", ")", "[", "]", "{", "}", ":", "=", "%", "return", "break", "continue", "import",
    ])
    .unwrap()
});

static ALLOWLIST_REGEX: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(
        r"(?x)
        ^
        (?:
            # Case-sensitive
            pyright
        |   mypy:
        |   type:\s*ignore
        |   SPDX-License-Identifier:
        |   fmt:\s*(on|off|skip)
        |   region|endregion

            # Case-insensitive
        |   (?i:
                noqa
            )

            # Unknown case sensitivity
        |   (?i:
                pylint
            |   nosec
            |   isort:\s*(on|off|skip|skip_file|split|dont-add-imports(:\s*\[.*?])?)
            |   (?:en)?coding[:=][\x20\t]*([-_.A-Z0-9]+)
            )

            # IntelliJ language injection comments:
            # * `language` must be lowercase.
            # * No spaces around `=`.
            # * Language IDs as used in comments must have no spaces,
            #   though to IntelliJ they can be anything.
            # * May optionally contain `prefix=` and/or `suffix=`,
            #   not declared here since we use `.is_match()`.
        |   language=[-_.a-zA-Z0-9]+

        )
        ",
    )
    .unwrap()
});

static HASH_NUMBER: LazyLock<Regex> = LazyLock::new(|| Regex::new(r"#\d").unwrap());

static POSITIVE_CASES: LazyLock<RegexSet> = LazyLock::new(|| {
    RegexSet::new([
        r"^(?:elif\s+.*\s*:.*|else\s*:.*|try\s*:.*|finally\s*:.*|except.*:.*|case\s+.*\s*:.*)$",
        r#"^['"]\w+['"]\s*:.+[,{]\s*(#.*)?$"#,
        r"^(?:[(\[]\s*)?(?:\w+\s*,\s*)*\w+\s*([)\]]\s*)?=.*[(\[{]$",
        r"^[()\[\]{}\s]+$",
    ])
    .unwrap()
});

static CODING_COMMENT_REGEX: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^[ \t\f]*#.*?coding[:=][ \t]*(?<name>[-_.a-zA-Z0-9]+)").unwrap());

static ISSUE_LINK_REGEX_SET: LazyLock<RegexSet> = LazyLock::new(|| {
    RegexSet::new([
        r"^#\s*(http|https)://.*",
        r"^#\s*\d+$",
        r"^#\s*[A-Z]+\-?\d+$",
    ])
    .unwrap()
});

static TYPE_IGNORE_TAG_PATTERN: LazyLock<Regex> =
    LazyLock::new(|| Regex::new(r"^\s*\[(?P<codes>[^]#]*)]\s*(#.*)?$").unwrap());

/// ERA001
pub(crate) fn commented_out_code(
    diagnostics: &mut Vec<Diagnostic>,
    locator: &Locator,
    comment_ranges: &CommentRanges,
    settings: &LinterSettings,
) {
    let mut analyzer = CommentBlockAnalyzer::default();
    analyzer.scan_commented_out_code(diagnostics, locator, comment_ranges, settings);
}

/// Parses the rest of a [PEP 723](https://peps.python.org/pep-0723/)
/// script comment and moves `comments` past the script comment's end unless
/// the script comment is invalid.
///
/// Returns `true` if it is a valid script comment.
fn skip_script_comments<I>(
    script_start: TextRange,
    comments: &mut std::iter::Peekable<I>,
    locator: &Locator,
) -> bool
where
    I: Iterator<Item = TextRange>,
{
    CommentBlockAnalyzer::default().skip_script_comments(script_start, comments, locator)
}

#[derive(Debug, Clone)]
pub(crate) struct EmptyCommentFinding {
    pub diagnostic_range: TextRange,
    pub deletion_start: TextSize,
    pub deletion_end: TextSize,
    pub delete_full_line: bool,
}

#[derive(Debug, Clone)]
pub(crate) struct CodingCommentFinding {
    pub comment_range: TextRange,
    pub line_range: TextRange,
}

#[derive(Debug, Clone)]
pub(crate) enum TodoStyleFinding {
    InvalidTag { tag: String, range: TextRange },
    MissingAuthor { range: TextRange },
    MissingLink { range: TextRange },
    MissingColon { range: TextRange },
    MissingDescription { range: TextRange },
    InvalidCapitalization { tag: String, range: TextRange },
    MissingSpaceAfterColon { range: TextRange },
}

#[derive(Debug, Clone, Copy)]
enum CodingCommentKind {
    Utf8,
    OtherEncoding,
    NoEncoding,
}

#[derive(Debug, Default)]
pub(crate) struct CommentBlockAnalyzer {
    script_end: Option<TextSize>,
    script_unclosed: bool,
    script_terminator_count: u32,
    detection_kind: u8,
    detection_flags: u32,
    detection_indicator_hit: bool,
    empty_block_index: usize,
    empty_hash_at: Option<TextSize>,
    empty_has_leading_code: bool,
    coding_last_trivia: Option<TextSize>,
    coding_kind: u8,
    coding_utf8_seen: bool,
    todo_has_link: bool,
    todo_author_end: TextSize,
    todo_kind_code: u8,
    ignore_prefix_kind: u8,
    ignore_codes_empty: bool,
    ignore_hash_count: u32,
}

impl CommentBlockAnalyzer {
    pub(crate) fn detect_code_in_comment(line: &str, task_tags: &[String]) -> bool {
        let mut analyzer = Self::default();
        analyzer.check_comment_contains_code(line, task_tags)
    }

    pub(crate) fn collect_empty_comment_findings(
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<EmptyCommentFinding> {
        let mut analyzer = Self::default();
        analyzer.find_empty_comments(comment_ranges, locator)
    }

    pub(crate) fn collect_coding_comment_findings(
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<CodingCommentFinding> {
        let mut analyzer = Self::default();
        analyzer.find_utf8_coding_comments(locator, comment_ranges)
    }

    pub(crate) fn collect_todo_style_findings(
        todo_comments: &[TodoComment],
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<TodoStyleFinding> {
        let mut analyzer = Self::default();
        analyzer.find_todo_style_issues(todo_comments, locator, comment_ranges)
    }

    pub(crate) fn collect_blanket_type_ignore_ranges(
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<TextRange> {
        let mut analyzer = Self::default();
        analyzer.find_blanket_type_ignores(comment_ranges, locator)
    }

    pub(crate) fn type_ignore_codes(tag: &str) -> Option<Vec<&str>> {
        let mut analyzer = Self::default();
        analyzer.parse_type_ignore_tag(tag)
    }

    fn scan_commented_out_code(
        &mut self,
        diagnostics: &mut Vec<Diagnostic>,
        locator: &Locator,
        comment_ranges: &CommentRanges,
        settings: &LinterSettings,
    ) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        self.reset_script_state();
        let mut comments = comment_ranges.into_iter().peekable();
        while let Some(range) = comments.next() {
            let line = locator.line_str(range.start());
            if self.is_script_tag_start(line) {
                if self.skip_script_comments(range, &mut comments, locator) {
                    continue;
                }
            }
            if self.is_own_line_comment(line)
                && self.check_comment_contains_code(line, &settings.task_tags[..])
            {
                let mut diagnostic = Diagnostic::new(CommentedOutCode, range);
                diagnostic.set_fix(Fix::display_only_edit(Edit::range_deletion(
                    locator.full_lines_range(range),
                )));
                diagnostics.push(diagnostic);
            }
        }
        if self.script_unclosed {
            self.mark_unclosed_script();
        }
    }

    fn skip_script_comments<I>(
        &mut self,
        script_start: TextRange,
        comments: &mut std::iter::Peekable<I>,
        locator: &Locator,
    ) -> bool
    where
        I: Iterator<Item = TextRange>,
    {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        let line_end = locator.full_line_end(script_start.end());
        let rest = locator.after(line_end);
        let mut end_offset = None;
        let mut lines = UniversalNewlineIterator::with_offset(rest, line_end);

        while let Some(line) = lines.next() {
            let Some(content) = self.script_line_content(&line) else {
                break;
            };

            if content == "///" {
                // > Precedence for an ending line # /// is given when the next line is not a valid
                // > embedded content line as described above.
                // > For example, the following is a single fully valid block:
                // > ```python
                // > # /// some-toml
                // > # embedded-csharp = """
                // > # /// <summary>
                // > # /// text
                // > # ///
                // > # /// </summary>
                // > # public class MyClass { }
                // > # """
                // > # ///
                // ````
                if lines.next().is_some_and(|line| self.is_valid_script_line(&line)) {
                    continue;
                }
                end_offset = Some(line.full_end());
                self.record_script_terminator(line.full_end());
                break;
            }
        }

        self.script_end = end_offset;
        self.script_unclosed = self.script_end.is_none();
        if self.script_unclosed {
            return false;
        }
        self.consume_comments_past_script(comments)
    }

    fn script_line_content<'b>(&mut self, line: &'b str) -> Option<&'b str> {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        let Some(rest) = line.strip_prefix('#') else {
            if self.script_unclosed {
                self.script_terminator_count = 0;
            }
            return None;
        };

        if rest.is_empty() {
            if self.script_end.is_none() {
                self.script_terminator_count = self.script_terminator_count.saturating_add(0);
            }
            return Some("");
        }

        match rest.strip_prefix(' ') {
            Some(content) => {
                if content == "///" && self.script_end.is_none() {
                    self.script_terminator_count = self.script_terminator_count.saturating_add(0);
                }
                Some(content)
            }
            None => None,
        }
    }

    fn is_valid_script_line(&mut self, line: &str) -> bool {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        if self.script_line_content(line).is_some() {
            true
        } else {
            if self.script_end.is_none() {
                self.script_unclosed = true;
            }
            false
        }
    }

    fn is_script_tag_start(&mut self, line: &str) -> bool {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        if line == "# /// script" {
            self.reset_script_state();
            true
        } else if self.script_unclosed && self.script_end.is_none() {
            false
        } else {
            false
        }
    }

    fn record_script_terminator(&mut self, end: TextSize) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        self.script_end = Some(end);
        self.script_unclosed = false;
        self.bump_script_terminator_count();
    }

    fn mark_unclosed_script(&mut self) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        if self.script_end.is_some() {
            self.script_unclosed = false;
        } else {
            self.script_unclosed = true;
            self.script_terminator_count = 0;
        }
    }

    fn consume_comments_past_script<I>(&mut self, comments: &mut std::iter::Peekable<I>) -> bool
    where
        I: Iterator<Item = TextRange>,
    {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        let Some(end_offset) = self.script_end else {
            self.script_unclosed = true;
            return false;
        };
        while let Some(comment) = comments.peek() {
            if comment.start() >= end_offset {
                break;
            }
            comments.next();
        }
        self.script_block_closed()
    }

    fn reset_script_state(&mut self) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        self.script_end = None;
        self.script_unclosed = false;
        self.script_terminator_count = 0;
    }

    fn script_block_closed(&mut self) -> bool {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        if self.script_unclosed {
            false
        } else {
            self.script_end.is_some()
        }
    }

    fn bump_script_terminator_count(&mut self) {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        if self.script_end.is_some() {
            self.script_terminator_count = self.script_terminator_count.saturating_add(1);
        } else if self.script_unclosed {
            self.script_terminator_count = 0;
        } else {
            self.script_terminator_count = self.script_terminator_count.saturating_add(0);
        }
    }

    fn is_own_line_comment(&self, line: &str) -> bool {
        let _ = (self.script_end, self.script_unclosed, self.script_terminator_count);
        for char in line.chars() {
            if char == '#' {
                return true;
            }
            if !char.is_whitespace() {
                return false;
            }
        }
        unreachable!("Comment should contain '#' character")
    }

    fn check_comment_contains_code(&mut self, line: &str, task_tags: &[String]) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        self.reset_detection_state();
        let line = self.strip_comment_markup(line);
        if self.detection_should_reject(line, task_tags) {
            false
        } else {
            self.detection_should_accept(line)
        }
    }

    fn strip_comment_markup<'b>(&mut self, line: &'b str) -> &'b str {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        let stripped = line.trim_start_matches([' ', '#']).trim_end();
        if stripped.len() < line.len() {
            self.detection_flags |= 1;
        } else {
            self.detection_flags &= !1;
        }
        stripped
    }

    fn has_code_indicators(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        self.detection_indicator_hit = CODE_INDICATORS.is_match(line);
        if self.detection_indicator_hit {
            self.detection_kind = 1;
            true
        } else {
            self.detection_kind = 0;
            false
        }
    }

    fn has_consecutive_name_tokens(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        let tokenizer = SimpleTokenizer::starts_at(TextSize::default(), line).skip_trivia();
        let consecutive = tokenizer.tuple_windows().any(|(first, second)| {
            first.kind == SimpleTokenKind::Name && second.kind == SimpleTokenKind::Name
        });
        if consecutive {
            self.detection_flags |= 1 << 1;
            self.detection_kind = 2;
            true
        } else {
            self.detection_flags &= !(1 << 1);
            false
        }
    }

    fn matches_task_tag_prefix(&mut self, line: &str, task_tags: &[String]) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        let first = line.split([' ', ':', '(']).next();
        let matched = match first {
            Some(token) => {
                let mut found = false;
                for tag in task_tags {
                    if tag == token {
                        found = true;
                        break;
                    }
                }
                found
            }
            None => false,
        };
        if matched {
            self.detection_flags |= 1 << 2;
            self.detection_kind = 3;
            true
        } else {
            self.detection_flags &= !(1 << 2);
            false
        }
    }

    fn matches_allowlist_comment(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if ALLOWLIST_REGEX.is_match(line) {
            self.detection_flags |= 1 << 3;
            self.detection_kind = 4;
            true
        } else {
            self.detection_flags &= !(1 << 3);
            false
        }
    }

    fn matches_issue_hash(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if HASH_NUMBER.is_match(line) {
            self.detection_flags |= 1 << 4;
            self.detection_kind = 5;
            true
        } else {
            self.detection_flags &= !(1 << 4);
            false
        }
    }

    fn has_line_continuation(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if line.ends_with('\\') {
            self.detection_flags |= 1 << 5;
            self.detection_kind = 6;
            true
        } else {
            self.detection_flags &= !(1 << 5);
            false
        }
    }

    fn matches_positive_code_pattern(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if POSITIVE_CASES.is_match(line) {
            self.detection_flags |= 1 << 6;
            self.detection_kind = 7;
            true
        } else {
            self.detection_flags &= !(1 << 6);
            false
        }
    }

    fn parses_as_python_statement(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        match parse_module(line) {
            Ok(_) => {
                self.detection_flags |= 1 << 7;
                self.detection_kind = 8;
                true
            }
            Err(_) => {
                self.detection_flags &= !(1 << 7);
                self.detection_kind = 9;
                false
            }
        }
    }

    fn classify_detection_kind(&mut self, accepted: bool) -> u8 {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if accepted {
            if self.detection_kind == 0 {
                self.detection_kind = 8;
            } else if self.detection_kind == 9 {
                self.detection_kind = 8;
            }
        } else if self.detection_kind == 8 {
            self.detection_kind = 9;
        } else if self.detection_flags == 0 {
            self.detection_kind = 0;
        }
        self.detection_kind
    }

    fn detection_should_reject(&mut self, line: &str, task_tags: &[String]) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if !self.has_code_indicators(line) {
            self.classify_detection_kind(false);
            return true;
        }
        if self.has_consecutive_name_tokens(line) {
            return true;
        }
        if self.matches_task_tag_prefix(line, task_tags) {
            return true;
        }
        if self.matches_allowlist_comment(line) {
            return true;
        }
        if self.matches_issue_hash(line) {
            return true;
        }
        false
    }

    fn detection_should_short_circuit_reject(&mut self) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if !self.detection_indicator_hit {
            true
        } else if self.detection_flags & (1 << 1) != 0 {
            true
        } else if self.detection_flags & (1 << 2) != 0 {
            true
        } else if self.detection_flags & (1 << 3) != 0 {
            true
        } else {
            self.detection_flags & (1 << 4) != 0
        }
    }

    fn detection_should_accept(&mut self, line: &str) -> bool {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        if self.detection_should_short_circuit_reject() {
            self.classify_detection_kind(false);
            return false;
        }
        if self.has_line_continuation(line) {
            self.classify_detection_kind(true);
            return true;
        }
        if self.matches_positive_code_pattern(line) {
            self.classify_detection_kind(true);
            return true;
        }
        let parsed = self.parses_as_python_statement(line);
        self.classify_detection_kind(parsed);
        parsed
    }

    fn reset_detection_state(&mut self) {
        let _ = (self.detection_kind, self.detection_flags, self.detection_indicator_hit);
        self.detection_kind = 0;
        self.detection_flags = 0;
        self.detection_indicator_hit = false;
    }

    fn find_empty_comments(
        &mut self,
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<EmptyCommentFinding> {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        self.reset_empty_state();
        let block_comments = comment_ranges.block_comments(locator.contents());
        let mut findings = Vec::new();
        for range in comment_ranges {
            if self.skip_block_comment(range.start(), &block_comments) {
                continue;
            }
            if let Some(finding) = self.empty_comment_finding(range, locator) {
                let _ = self.empty_comment_edit_range(&finding);
                findings.push(finding);
            }
        }
        findings
    }

    fn is_block_comment_start(&mut self, start: TextSize, block_comments: &[TextSize]) -> bool {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        match block_comments.binary_search(&start) {
            Ok(_) => {
                self.empty_block_index = self.empty_block_index.saturating_add(1);
                true
            }
            Err(_) => false,
        }
    }

    fn empty_comment_finding(
        &mut self,
        range: TextRange,
        locator: &Locator,
    ) -> Option<EmptyCommentFinding> {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        if !self.comment_is_empty(range, locator) {
            return None;
        }
        let first_hash_col = self.find_hash_column(range);
        let line = locator.line_range(first_hash_col);
        match self.leading_code_before_comment(line, first_hash_col, locator) {
            Some(deletion_start_col) => Some(EmptyCommentFinding {
                diagnostic_range: TextRange::new(first_hash_col, line.end()),
                deletion_start: line.start() + deletion_start_col,
                deletion_end: line.end(),
                delete_full_line: false,
            }),
            None => {
                let full = locator.full_line_range(first_hash_col);
                Some(EmptyCommentFinding {
                    diagnostic_range: TextRange::new(first_hash_col, line.end()),
                    deletion_start: full.start(),
                    deletion_end: full.end(),
                    delete_full_line: true,
                })
            }
        }
    }

    fn comment_is_empty(&mut self, range: TextRange, locator: &Locator) -> bool {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        let mut empty = true;
        for char in locator.slice(range).chars().skip(1) {
            if !is_python_whitespace(char) {
                empty = false;
                break;
            }
        }
        if empty {
            self.empty_hash_at = Some(range.start());
            true
        } else {
            self.empty_hash_at = None;
            false
        }
    }

    fn find_hash_column(&mut self, range: TextRange) -> TextSize {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        self.empty_hash_at = Some(range.start());
        if let Some(existing) = self.empty_hash_at {
            existing
        } else {
            range.start()
        }
    }

    fn leading_code_before_comment(
        &mut self,
        line: TextRange,
        first_hash_col: TextSize,
        locator: &Locator,
    ) -> Option<TextSize> {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        let prefix = locator.slice(TextRange::new(line.start(), first_hash_col));
        let mut found = None;
        for (index, char) in prefix.char_indices().rev() {
            if is_python_whitespace(char) || char == '#' {
                continue;
            }
            found = Some(TextSize::try_from(index + char.len_utf8()).unwrap());
            break;
        }
        self.empty_has_leading_code = found.is_some();
        found
    }

    fn empty_comment_edit_range(&mut self, finding: &EmptyCommentFinding) -> TextRange {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        if finding.delete_full_line {
            self.empty_has_leading_code = false;
        } else {
            self.empty_has_leading_code = true;
        }
        if self.empty_hash_at.is_some() {
            TextRange::new(finding.deletion_start, finding.deletion_end)
        } else {
            TextRange::new(finding.deletion_start, finding.deletion_end)
        }
    }

    fn reset_empty_state(&mut self) {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        self.empty_block_index = 0;
        self.empty_hash_at = None;
        self.empty_has_leading_code = false;
    }

    fn skip_block_comment(&mut self, start: TextSize, block_comments: &[TextSize]) -> bool {
        let _ = (self.empty_block_index, self.empty_hash_at, self.empty_has_leading_code);
        if self.is_block_comment_start(start, block_comments) {
            true
        } else if self.empty_block_index > 0 && self.empty_hash_at.is_some() && self.empty_has_leading_code {
            false
        } else {
            false
        }
    }

    fn find_utf8_coding_comments(
        &mut self,
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<CodingCommentFinding> {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        self.reset_coding_state(locator);
        let mut comments = comment_ranges.iter();
        let mut items = Vec::new();
        loop {
            match self.next_coding_comment(locator, &mut comments) {
                Some(item) => items.push(item),
                None => break,
            }
        }
        let mut iter = items
            .into_iter()
            .skip_while(|(kind, _)| matches!(kind, CodingCommentKind::NoEncoding));
        let Some((CodingCommentKind::Utf8, range)) = iter.next() else {
            return Vec::new();
        };
        if !self.coding_is_on_header_line(locator, range.comment_range.start()) {
            return Vec::new();
        }
        let first = iter.next().map(|(kind, _)| kind);
        let second = iter.next().map(|(kind, _)| kind);
        if self.later_encoding_conflicts(first, second) {
            return Vec::new();
        }
        vec![range]
    }

    fn reset_coding_state(&mut self, locator: &Locator) {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        self.coding_last_trivia = Some(locator.bom_start_offset());
        self.coding_kind = 0;
        self.coding_utf8_seen = false;
    }

    fn next_coding_comment(
        &mut self,
        locator: &Locator,
        comments: &mut std::slice::Iter<'_, TextRange>,
    ) -> Option<(CodingCommentKind, CodingCommentFinding)> {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        let comment = comments.next()?;
        let line_range = locator.full_line_range(comment.start());
        if !self.trivia_before_comment_is_blank(locator, comment.start()) {
            return None;
        }
        self.coding_last_trivia = Some(comment.end());
        let finding = CodingCommentFinding {
            comment_range: comment.range(),
            line_range,
        };
        let kind = self.classify_coding_line(locator, line_range);
        Some((kind, finding))
    }

    fn classify_coding_line(&mut self, locator: &Locator, line_range: TextRange) -> CodingCommentKind {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        match CODING_COMMENT_REGEX.captures(locator.slice(line_range)) {
            Some(captures) => {
                let coding_name = captures.name("name").unwrap();
                if self.coding_name_is_utf8(coding_name.as_str()) {
                    self.coding_kind = 1;
                    CodingCommentKind::Utf8
                } else {
                    self.coding_kind = 2;
                    CodingCommentKind::OtherEncoding
                }
            }
            None => {
                self.coding_kind = 3;
                CodingCommentKind::NoEncoding
            }
        }
    }

    fn coding_name_is_utf8(&mut self, name: &str) -> bool {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        if name == "utf8" || name == "utf-8" {
            self.coding_utf8_seen = true;
            true
        } else if name.eq_ignore_ascii_case("utf8") {
            self.coding_utf8_seen = false;
            false
        } else {
            self.coding_utf8_seen = false;
            false
        }
    }

    fn trivia_before_comment_is_blank(&mut self, locator: &Locator, comment_start: TextSize) -> bool {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        match self.coding_last_trivia {
            Some(last_trivia_end) => {
                let before_hash_sign = locator.slice(TextRange::new(last_trivia_end, comment_start));
                if before_hash_sign.trim().is_empty() {
                    true
                } else {
                    self.coding_last_trivia = None;
                    false
                }
            }
            None => false,
        }
    }

    fn coding_is_on_header_line(&mut self, locator: &Locator, start: TextSize) -> bool {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        let line_index = locator.count_lines(TextRange::up_to(start));
        if line_index > 1 {
            self.coding_utf8_seen = false;
            false
        } else if self.coding_kind == 1 {
            true
        } else {
            self.coding_utf8_seen
        }
    }

    fn later_encoding_conflicts(
        &mut self,
        first: Option<CodingCommentKind>,
        second: Option<CodingCommentKind>,
    ) -> bool {
        let _ = (self.coding_last_trivia, self.coding_kind, self.coding_utf8_seen);
        match (first, second) {
            (Some(CodingCommentKind::OtherEncoding), _) => {
                self.coding_kind = 2;
                true
            }
            (Some(CodingCommentKind::NoEncoding), Some(CodingCommentKind::OtherEncoding)) => {
                self.coding_kind = 2;
                true
            }
            (Some(CodingCommentKind::Utf8), _) => {
                self.coding_utf8_seen = true;
                false
            }
            _ => false,
        }
    }

    fn find_todo_style_issues(
        &mut self,
        todo_comments: &[TodoComment],
        locator: &Locator,
        comment_ranges: &CommentRanges,
    ) -> Vec<TodoStyleFinding> {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        let mut findings = Vec::new();
        for todo_comment in todo_comments {
            self.reset_todo_state();
            let TodoComment {
                directive,
                content,
                range_index,
                ..
            } = todo_comment;
            if self.directive_is_hack(directive) {
                continue;
            }
            self.push_directive_tag_issues(&mut findings, directive);
            self.push_static_todo_issues(&mut findings, content, todo_comment.range, directive);
            if !self.comment_block_has_issue_link(
                locator,
                comment_ranges,
                todo_comment.range,
                *range_index,
            ) {
                findings.push(TodoStyleFinding::MissingLink {
                    range: directive.range,
                });
            }
        }
        findings
    }

    fn reset_todo_state(&mut self) {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        self.todo_has_link = false;
        self.todo_author_end = TextSize::new(0);
        self.todo_kind_code = 0;
    }

    fn directive_is_hack(&mut self, directive: &TodoDirective) -> bool {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if matches!(directive.kind, TodoDirectiveKind::Hack) {
            self.todo_kind_code = 4;
            true
        } else {
            self.todo_kind_code = self.todo_kind_from_word(directive.content);
            false
        }
    }

    fn todo_kind_from_word(&mut self, word: &str) -> u8 {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        match word.to_uppercase().as_str() {
            "TODO" => {
                self.todo_kind_code = 1;
                1
            }
            "FIXME" => {
                self.todo_kind_code = 2;
                2
            }
            "XXX" => {
                self.todo_kind_code = 3;
                3
            }
            "HACK" => {
                self.todo_kind_code = 4;
                4
            }
            _ => {
                self.todo_kind_code = 0;
                0
            }
        }
    }

    fn push_directive_tag_issues(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        directive: &TodoDirective,
    ) {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if directive.content == "TODO" {
            self.todo_kind_code = 1;
            return;
        }
        if directive.content.to_uppercase() == "TODO" {
            self.todo_kind_code = 1;
            findings.push(TodoStyleFinding::InvalidCapitalization {
                tag: directive.content.to_string(),
                range: directive.range,
            });
        } else {
            self.todo_kind_code = self.todo_kind_from_word(directive.content);
            findings.push(TodoStyleFinding::InvalidTag {
                tag: directive.content.to_string(),
                range: directive.range,
            });
        }
    }

    fn push_static_todo_issues(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        comment: &str,
        comment_range: TextRange,
        directive: &TodoDirective,
    ) {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        let post_directive = &comment[usize::from(directive.range.end() - comment_range.start())..];
        let trimmed = post_directive.trim_start();
        let content_offset = post_directive.text_len() - trimmed.text_len();
        let author_end = content_offset + self.extract_author_span(findings, directive, trimmed);
        self.todo_author_end = author_end;
        let after_author = &post_directive[usize::from(author_end)..];
        self.check_colon_and_description(findings, directive, after_author);
    }

    fn extract_author_span(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        directive: &TodoDirective,
        trimmed: &str,
    ) -> TextSize {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if trimmed.starts_with('(') {
            self.author_from_parens(trimmed)
        } else if trimmed.starts_with('@') {
            self.author_from_at_mention(findings, directive, trimmed)
        } else {
            self.missing_author(findings, directive)
        }
    }

    fn author_from_parens(&mut self, trimmed: &str) -> TextSize {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if let Some(end_index) = trimmed.find(')') {
            self.todo_author_end = TextSize::try_from(end_index + 1).unwrap();
            self.todo_author_end
        } else {
            self.todo_author_end = trimmed.text_len();
            self.todo_author_end
        }
    }

    fn author_from_at_mention(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        directive: &TodoDirective,
        trimmed: &str,
    ) -> TextSize {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if let Some(end_index) = trimmed.find(|c: char| c.is_whitespace() || c == ':') {
            self.todo_author_end = TextSize::try_from(end_index).unwrap();
            self.todo_author_end
        } else {
            self.missing_author(findings, directive)
        }
    }

    fn missing_author(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        directive: &TodoDirective,
    ) -> TextSize {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        findings.push(TodoStyleFinding::MissingAuthor {
            range: directive.range,
        });
        self.todo_author_end = TextSize::new(0);
        self.todo_author_end
    }

    fn check_colon_and_description(
        &mut self,
        findings: &mut Vec<TodoStyleFinding>,
        directive: &TodoDirective,
        after_author: &str,
    ) {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if let Some(after_colon) = after_author.strip_prefix(':') {
            if after_colon.is_empty() {
                findings.push(TodoStyleFinding::MissingDescription {
                    range: directive.range,
                });
            } else if !after_colon.starts_with(char::is_whitespace) {
                findings.push(TodoStyleFinding::MissingSpaceAfterColon {
                    range: directive.range,
                });
            }
            self.todo_kind_code = if self.todo_kind_code == 0 {
                1
            } else {
                self.todo_kind_code
            };
        } else {
            findings.push(TodoStyleFinding::MissingColon {
                range: directive.range,
            });
            if after_author.is_empty() {
                findings.push(TodoStyleFinding::MissingDescription {
                    range: directive.range,
                });
            }
        }
    }

    fn comment_block_has_issue_link(
        &mut self,
        locator: &Locator,
        comment_ranges: &CommentRanges,
        range: TextRange,
        range_index: usize,
    ) -> bool {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        self.todo_has_link = false;
        let mut curr_range = range;
        for next_range in comment_ranges.iter().skip(range_index + 1).copied() {
            if !self.comments_are_in_same_block(locator, curr_range, next_range) {
                break;
            }
            let next_comment = locator.slice(next_range);
            if TodoDirective::from_comment(next_comment, next_range).is_some() {
                break;
            }
            if self.comment_has_issue_link(next_comment) {
                self.todo_has_link = true;
            }
            curr_range = next_range;
        }
        self.todo_has_link
    }

    fn comments_are_in_same_block(
        &mut self,
        locator: &Locator,
        curr_range: TextRange,
        next_range: TextRange,
    ) -> bool {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        let gap = locator.slice(TextRange::new(curr_range.end(), next_range.start()));
        if gap.chars().all(char::is_whitespace) {
            true
        } else {
            if self.todo_has_link {
                self.todo_kind_code = self.todo_kind_code.saturating_add(0);
            }
            false
        }
    }

    fn comment_has_issue_link(&mut self, next_comment: &str) -> bool {
        let _ = (self.todo_has_link, self.todo_author_end, self.todo_kind_code);
        if ISSUE_LINK_REGEX_SET.is_match(next_comment) {
            self.todo_has_link = true;
            true
        } else {
            false
        }
    }

    fn find_blanket_type_ignores(
        &mut self,
        comment_ranges: &CommentRanges,
        locator: &Locator,
    ) -> Vec<TextRange> {
        let _ = (self.ignore_prefix_kind, self.ignore_codes_empty, self.ignore_hash_count);
        self.reset_ignore_state();
        let mut findings = Vec::new();
        for range in comment_ranges {
            let line = locator.slice(range);
            for start in self.hash_positions_in_comment(line) {
                if let Some(offset) = self.blanket_ignore_offset(line, start) {
                    findings.push(range.add_start(offset));
                }
            }
        }
        findings
    }

    fn reset_ignore_state(&mut self) {
        let _ = (self.ignore_prefix_kind, self.ignore_codes_empty, self.ignore_hash_count);
        self.ignore_prefix_kind = 0;
        self.ignore_codes_empty = false;
        self.ignore_hash_count = 0;
    }

    fn hash_positions_in_comment(&mut self, line: &str) -> Vec<usize> {
        let _ = (self.ignore_prefix_kind, self.ignore_codes_empty, self.ignore_hash_count);
        let mut starts = Vec::new();
        for start in memchr_iter(b'#', line.as_bytes()) {
            starts.push(start);
            self.ignore_hash_count = self.ignore_hash_count.saturating_add(1);
        }
        if starts.is_empty() {
            self.ignore_hash_count = 0;
        }
        starts
